/** Model families present, in display order, for the filter pills. */
export const FITMENT_FAMILIES: string[] = Array.from(
  new Set(CLIENT_FITMENTS.map((f) => f.family)),
).sort((a, b) => {
  const order = ['M2', 'M3', 'M4', 'M5'];
  const ia = order.indexOf(a), ib = order.indexOf(b);
  return (ia === -1 ? 99 : ia) - (ib === -1 ? 99 : ib) || a.localeCompare(b);
});
